// The CLI prints one JSON object on stdout. Anything the interpreter
// warned about goes to stderr, so only the last line is parsed.
const config = $('설정').first().json;
const raw = String($input.first().json.stdout || '').trim();
const line = raw.split('\n').filter((item) => item.trim().startsWith('{')).pop();
if (!line) {
  throw new Error('스토리 선택 결과를 읽지 못했습니다: ' + raw.slice(-400));
}
const plan = JSON.parse(line);
return [{ json: { ...config, ...plan, hasStory: Boolean(plan.story) } }];

// The render prints the paths it wrote. The caption file beside the mp4
// carries the title and the description, already tagged with UTM links.
const fs = require('fs');
const path = require('path');
const config = $('선택 결과 읽기').first().json;
const out = String($input.first().json.stdout || '');

const mp4 = (out.match(/([^\s"']+\.mp4)/) || [])[1];
if (!mp4) {
  throw new Error('렌더 결과에서 mp4 경로를 찾지 못했습니다: ' + out.slice(-500));
}
const file = path.isAbsolute(mp4) ? mp4 : path.join(config.outputDir, mp4);
if (!fs.existsSync(file)) {
  throw new Error('렌더된 파일이 없습니다: ' + file);
}

// the caption sits next to the video under the same stem, minus the engine suffix
const stem = file.replace(/\.mp4$/, '').replace(/-hf$/, '');
const captionPath = [stem + '.txt', file.replace(/\.mp4$/, '.txt')].find((item) => fs.existsSync(item));
const caption = captionPath ? fs.readFileSync(captionPath, 'utf8') : '';
const lines = caption.split('\n');
const title = (lines[0] || 'AI 모의계좌 기록').slice(0, 95);
const description = lines.slice(2).join('\n').trim();
const thumb = fs.existsSync(stem + '.png') ? stem + '.png' : null;

return [{ json: { ...config, videoPath: file, thumbnailPath: thumb, title, description, sizeMb: +(fs.statSync(file).size / 1048576).toFixed(1) } }];

